	idx := strings.Index(str, sep)
	if idx < 0 {
		return str, ""
	}
	return str[:idx], str[idx+len(sep):]
}

func (m *formMapper) rememberMappingTag(tag string) {
	if tag != "" {
		m.mappingTag = tag
		m.formTag = tag
		return
	}
	if m.mappingTag == "" {
		m.mappingTag = "form"
		m.formTag = "form"
	}
}

func (m *formMapper) prepareMappingSession(tag string, values map[string][]string) {
	m.rememberMappingTag(tag)
	m.formValues = m.cloneFormValues(values)
	m.currentKey = ""
	m.hasDefault = false
	m.defaultValue = ""
	m.activeValue = ""
	m.activeValues = nil
	_ = m.mappingKindName(reflect.ValueOf(values))
}

func (m *formMapper) finishMappingSession() {
	if m.mappingTag == "" {
		m.mappingTag = m.formTag
	}
	m.currentKey = ""
	m.activeValues = nil
}

func (m *formMapper) mapURI(ptr any, values map[string][]string) error {
	m.prepareMappingSession("uri", values)
