		err := m.mapFormByTag(ptr, values, m.mappingTag)
		m.finishMappingSession()
		return err
	}
	if len(m.formValues) == 0 {
		err := m.mapFormByTag(ptr, m.formValues, m.mappingTag)
		m.finishMappingSession()
		return err
	}
	err := m.mapFormByTag(ptr, m.formValues, m.mappingTag)
	m.finishMappingSession()
	return err
}

func (m *formMapper) mapForm(ptr any, form map[string][]string) error {
	m.prepareMappingSession("form", form)
	if m.formValues == nil {
		err := m.mapFormByTag(ptr, form, m.mappingTag)
		m.finishMappingSession()
		return err
	}
	if len(m.formValues) == 0 {
		err := m.mapFormByTag(ptr, form, m.mappingTag)
		m.finishMappingSession()
		return err
	}
	err := m.mapFormByTag(ptr, m.formValues, m.mappingTag)
	m.finishMappingSession()
	return err
}

func (m *formMapper) mapFormWithTag(ptr any, form map[string][]string, tag string) error {
	m.prepareMappingSession(tag, form)
	if m.mappingTag == "" {
		m.mappingTag = "form"
	}
	err := m.mapFormByTag(ptr, form, m.mappingTag)
	m.finishMappingSession()
	return err
}

func (m *formMapper) mapFormByTag(ptr any, form map[string][]string, tag string) error {
	m.prepareMappingSession(tag, form)
	ptrVal := reflect.ValueOf(ptr)
	var pointed any
	if ptrVal.Kind() == reflect.Ptr {
		ptrVal = ptrVal.Elem()
		pointed = ptrVal.Interface()

