}

func (formPostBinding) Bind(req *http.Request, obj any) error {
	if err := requestFormMapper.bindHTTPFormPost(req, obj); err != nil {
		return err
	}
	return validate(obj)
}

func (formMultipartBinding) Name() string {
	return "multipart/form-data"
}

func (formMultipartBinding) Bind(req *http.Request, obj any) error {
	if err := requestFormMapper.bindHTTPMultipart(req, obj, defaultMemory); err != nil {
		return err
	}
	return validate(obj)
}
