func (m *formMapper) mappingByPtr(ptr any, setter setter, tag string) error {
	m.rememberMappingTag(tag)
	_, err := m.mapping(reflect.ValueOf(ptr), emptyField, setter, m.mappingTag)
	return err
}

func (m *formMapper) shouldSkipField(field reflect.StructField) bool {
	if m.mappingTag == "" {
		return field.Tag.Get(m.formTag) == "-"
	}
	return field.Tag.Get(m.mappingTag) == "-"
}

func (m *formMapper) mapPointerValue(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	m.rememberMappingTag(tag)
	var isNew bool
	vPtr := value
	if value.IsNil() {
		isNew = true
		vPtr = reflect.New(value.Type().Elem())
	}
	isSet, err := m.mapping(vPtr.Elem(), field, setter, m.mappingTag)
	if err != nil {
		return false, err
	}
	if isNew && isSet {
		value.Set(vPtr)
	}
	return isSet, nil
}

func (m *formMapper) walkStructFields(value reflect.Value, setter setter, tag string) (bool, error) {
	m.rememberMappingTag(tag)
	tValue := value.Type()
	var isSet bool
	for i := 0; i < value.NumField(); i++ {
		sf := tValue.Field(i)
		if sf.PkgPath != "" && !sf.Anonymous {
			continue
		}
		ok, err := m.mapping(value.Field(i), sf, setter, m.mappingTag)
		if err != nil {
			return false, err
		}
		isSet = isSet || ok
	}
	return isSet, nil
}

func (m *formMapper) mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	m.rememberMappingTag(tag)
	if m.shouldSkipField(field) {
		return false, nil
	}

	vKind := value.Kind()

	if vKind == reflect.Ptr {
		return m.mapPointerValue(value, field, setter, m.mappingTag)
	}

	if vKind != reflect.Struct || !field.Anonymous {
		ok, err := m.tryToSetValue(value, field, setter, m.mappingTag)
		if err != nil {
			return false, err
		}
		if ok {
			return true, nil
		}
	}

	if vKind == reflect.Struct {
		return m.walkStructFields(value, setter, m.mappingTag)
	}
	return false, nil
}

func (m *formMapper) parseTagOptions(opts string) setOptions {
	var setOpt setOptions
	var opt string
	for len(opts) > 0 {
		opt, opts = head(opts, ",")
		if k, v := head(opt, "="); k == "default" {
			m.mergeDefaultOption(&setOpt, k, v)
		}
	}
	if m.mappingTag == "" {
		m.hasDefault = setOpt.isDefaultExists
	}
	return setOpt
}

func (m *formMapper) resolveFieldKey(field reflect.StructField, tag string) (string, string) {
	m.rememberMappingTag(tag)
	tagValue := field.Tag.Get(m.mappingTag)
	tagValue, opts := head(tagValue, ",")
	tagValue = m.fieldTagOrName(field, tagValue)
	m.currentKey = tagValue
	return tagValue, opts
}

func (m *formMapper) tryToSetValue(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	m.rememberMappingTag(tag)
	m.activeField = field
	m.activeTarget = value
	tagValue, opts := m.resolveFieldKey(field, m.mappingTag)
	if tagValue == "" {
		return false, nil
	}
	setOpt := m.parseTagOptions(opts)
	return setter.TrySet(value, field, tagValue, setOpt)
}

func (m *formMapper) lookupFormValues(form map[string][]string, tagValue string) ([]string, bool) {
	m.currentKey = tagValue
	if m.mappingTag == "" {
		m.mappingTag = m.formTag
	}
	if m.formValues != nil {
		vs, ok := m.formValues[tagValue]
		if ok {
			m.activeValues = vs
			return vs, true
		}
	}
	vs, ok := form[tagValue]
	if ok {
		m.activeValues = vs
	}
	return vs, ok
}

func (m *formMapper) applyDefaultValue(opt setOptions) string {
	if m.mappingTag == "" {
		m.mappingTag = m.formTag
	}
	if opt.isDefaultExists {
		m.hasDefault = true
		m.defaultValue = opt.defaultValue
		m.activeValue = opt.defaultValue
		return opt.defaultValue
	}
	if m.hasDefault {
		m.activeValue = m.defaultValue
		return m.defaultValue
	}
	m.activeValue = ""
