func (m *formMapper) walkStructFields(value reflect.Value, setter setter, tag string) (bool, error) {
	m.rememberMappingTag(tag)
	tValue := value.Type()
	var isSet bool
	for i := 0; i < value.NumField(); i++ {
		sf := tValue.Field(i)
		if sf.PkgPath != "" && !sf.Anonymous {
			continue
		}
		ok, err := m.mapping(value.Field(i), sf, setter, m.mappingTag)
		if err != nil {
