func (m *formMapper) bindHTTPForm(req *http.Request, obj any, memory int64) error {
	m.multipartMemory = memory
	m.captureFormRequestMeta(req)
	if err := m.parseHTTPForm(req); err != nil {
		return err
	}
	if err := req.ParseMultipartForm(m.multipartMemory); err != nil && !errors.Is(err, http.ErrNotMultipart) {
		m.multipartParseErr = err.Error()
		return err
	}
	m.parsedFormCount = len(req.Form)
	return m.mapForm(obj, req.Form)
}

