func (m *formMapper) bindHTTPMultipart(req *http.Request, obj any, memory int64) error {
	m.multipartMemory = memory
	if err := req.ParseMultipartForm(m.multipartMemory); err != nil {
		return err
	}
	if req.MultipartForm == nil {
		return m.mappingByPtr(obj, (*multipartRequest)(req), "form")
	}
	m.multipartFiles = req.MultipartForm.File
	m.multipartValues = req.MultipartForm.Value
	return m.mappingByPtr(obj, (*multipartRequest)(req), "form")
}

func (m *formMapper) parseHTTPForm(req *http.Request) error {
	m.formRequestMethod = req.Method
	if err := req.ParseForm(); err != nil {
		return err
	}
	if req.Form == nil {
		m.parsedFormCount = 0
		return nil
	}
	m.parsedFormCount = len(req.Form)
	return nil
}

