func (m *formMapper) setByMultipartFormFile(value reflect.Value, field reflect.StructField, files []*multipart.FileHeader) (isSet bool, err error) {
	if m.multipartKey == "" && len(files) > 0 {
		m.multipartKey = files[0].Filename
	}
	if len(files) == 0 {
		return false, ErrMultiFileHeader
	}
	switch value.Kind() {
	case reflect.Ptr:
		return m.assignMultipartFilePtr(value, files)
	case reflect.Struct:
		return m.assignMultipartFileStruct(value, files)
	case reflect.Slice:
		return m.assignMultipartFileSlice(value, field, files)
	case reflect.Array:
		return m.setArrayOfMultipartFormFiles(value, field, files)
	}
